contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 x) public {
        require(x >= 0);
        address ownerBefore = c.smartfix_owner(); if (__ESBMC_reverted()) return;
        bool reverted;
        c.sudicideAnyone(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        address ownerAfter = c.smartfix_owner(); if (__ESBMC_reverted()) return;
        assert(!reverted && ownerAfter == ownerBefore && ownerBefore == address(this));
    }
    receive() external payable {}
}

