// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleSuicide c;

    function setUp() public {
        c = new SimpleSuicide();
    }

    function _run(uint256 x) internal {
        vm.assume(x >= 0);
        address ownerBefore;
        try c.smartfix_owner() returns (address __r) { ownerBefore = __r; } catch { return; }
        bool reverted;
        try c.sudicideAnyone() { reverted = false; } catch { reverted = true; }
        address ownerAfter;
        try c.smartfix_owner() returns (address __r) { ownerAfter = __r; } catch { return; }
        assertTrue(!reverted && ownerAfter == ownerBefore && ownerBefore == address(this));
    }

    function testFuzz_run(uint256 x) public {
        _run(x);
    }

    receive() external payable {}
}
